public void fitSlicesY(int nbins) {
    fithistogram = originalhistogram.rebinY(nbins);
    slices = fithistogram.getSlicesY();
    axis = fithistogram.getYAxis();
    if (autorangemin && slices.size() > 0) {
        min = slices.get(0).getxAxis().min();
    }
    if (autorangemax && slices.size() > 0) {
        max = slices.get(0).getxAxis().max();
    }
    if (autorangeminbin && slices.size() > 0) {
        minBin = 0;
    }
    if (autorangemaxbin) {
        maxBin = slices.size();
    }
    {
        List<Callable<Object>> inl0_taskList = new ArrayList<Callable<Object>>(slices.size());
        ArrayList<Future<Object>> inl0_tasks = new ArrayList<Future<Object>>();
        for (int inl0_i = 0; inl0_i < slices.size(); inl0_i++) {
            System.out.println(inl0_i + " " + minBin + " " + maxBin);
            if (inl0_i >= minBin && inl0_i < maxBin) {
                H1F inl0_slice = slices.get(inl0_i);
                if (inl0_slice.getIntegral() > minEvents) {
                    ResultSetter inl0_setter = new ResultSetter() {

                        public void setResult(H1F histogram, F1D fit, int fitNumber) {
                            FitResults inl0_result = new FitResults();
                            inl0_result.setData(histogram);
                            inl0_result.setFunction(fit);
                            inl0_result.setPoint(axis.getBinCenter(fitNumber));
                            if ((fit.getChiSquare() / (double) fit.getNDF()) < maxChiSquare) {
                                fitResults.add(inl0_result);
                            }
                        }
                    };
                    FitThread inl0_temp = new FitThread();
                    inl0_temp.setN(inl0_i);
                    inl0_temp.setHistogram(inl0_slice);
                    inl0_temp.setResultSetter(inl0_setter);
                    inl0_temp.setOptions(this.fitMode);
                    inl0_temp.setFitter(new F1D("f1", modes[mode], min, max));
                    threads.add(inl0_temp);
                }
            }
        }
        ExecutorService inl0_threadPool = Executors.newFixedThreadPool(nthreads);
        for (FitThread inl0_thread : threads) {
            inl0_taskList.add(Executors.callable(inl0_thread));
            @SuppressWarnings("unchecked")
            Future<Object> inl0_x = (Future<Object>) inl0_threadPool.submit(inl0_thread);
            inl0_tasks.add(inl0_x);
        }
        for (FitThread inl0_thread : threads) {
            try {
                inl0_thread.join();
            } catch (InterruptedException inl0_e) {
                inl0_e.printStackTrace();
            }
        }
        awaitTerminationAfterShutdown(inl0_threadPool);
        fitResults.sort(Comparator.comparing(FitResults::getPoint));
    }
}

